package com.chatgptcourses.attestations.service;

import static com.chatgptcourses.account.service.AccountOperations.*;
import static com.chatgptcourses.attestations.service.AttestationTypes.*;
import com.chatgptcourses.account.service.AccountOperations;
import com.chatgptcourses.shared.http.ApiError;
import java.nio.charset.StandardCharsets;
import java.sql.Timestamp;
import java.time.Instant;
import java.util.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Isolation;
import org.springframework.transaction.annotation.Transactional;

@Service
public class AttestationService {
    private final AccountOperations db;
    public AttestationService(AccountOperations db){this.db=db;}
    @Transactional(readOnly=true,isolation=Isolation.REPEATABLE_READ)
    public AttestationEnrollmentPage enrollments(UUID actor,int page,int size){db.authorization.require(actor,"attestations.read");page(page,size);long total=db.jdbc.queryForObject("SELECT count(*) FROM learning_enrollments WHERE owner_id=?",Long.class,actor);var items=db.jdbc.query("SELECT * FROM learning_enrollments WHERE owner_id=? ORDER BY created_at DESC,id LIMIT ? OFFSET ?",(r,n)->new AttestationEnrollment(r.getObject("id",UUID.class),r.getObject("course_resource_id",UUID.class),r.getObject("course_version_id",UUID.class),r.getInt("course_version_number"),r.getString("course_title"),r.getString("enrolled_locale"),instant(r,"created_at")),actor,size,(long)page*size);return new AttestationEnrollmentPage(items,page,size,total);}
    @Transactional(readOnly=true,isolation=Isolation.REPEATABLE_READ)
    public AttestationEligibility eligibility(UUID actor,UUID enrollment,String locale){db.authorization.require(actor,"attestations.read");locale(locale);var e=evidence(actor,enrollment);if(ParticipationHtml.render(new UUID(0,0),locale,Instant.parse("2000-01-01T00:00:00.123456789Z"),e).length>262144)throw error(ApiError.ATTESTATION_DOCUMENT_TOO_LARGE);return eligibility(e,locale);}
    private AttestationEligibility eligibility(ParticipationEvidence e,String locale){boolean name=e.participantName()!=null&&!e.participantName().isBlank();boolean participated=e.activities().stream().anyMatch(a->a.declaredCompletedAt()!=null)||!e.quizzes().isEmpty()||!e.selfAssessments().isEmpty();var criteria=List.of(new AttestationCriterion("PROFILE_NAME_PRESENT",name),new AttestationCriterion("PERSISTED_PARTICIPATION_PRESENT",participated));return new AttestationEligibility(e.enrollmentId(),"PARTICIPATION",locale,name&&participated,criteria.stream().filter(c->!c.met()).map(AttestationCriterion::code).toList(),criteria,hex(db.hash(e)),e);}
    @Transactional
    public AttestationCreation issue(UUID actor,UUID context,UUID enrollment,String idempotencyKey,IssueAttestation command){db.authorization.mutation(actor,context,"attestations.issue");check(command!=null);locale(command.locale());check(command.expectedEvidenceFingerprint()!=null&&command.expectedEvidenceFingerprint().matches("[a-f0-9]{64}"));UUID key=key(idempotencyKey);byte[] requestHash=db.hash(Arrays.asList(enrollment,command));db.lock(actor);db.authorization.mutation(actor,context,"attestations.issue");UUID replay=db.replay(actor,"ATTESTATION_ISSUE",key,requestHash);if(replay!=null)return new AttestationCreation(load(actor,replay),false);
        if(db.jdbc.query("SELECT id FROM learning_enrollments WHERE id=? AND owner_id=? FOR SHARE",(r,n)->r.getObject(1,UUID.class),enrollment,actor).isEmpty())throw error(ApiError.RESOURCE_NOT_FOUND);
        db.jdbc.query("SELECT p.id FROM learning_activity_progress p WHERE p.enrollment_id=? ORDER BY p.id FOR SHARE",(r,n)->r.getObject(1,UUID.class),enrollment);
        var e=evidence(actor,enrollment);var readiness=eligibility(e,command.locale());if(!readiness.evidenceFingerprint().equals(command.expectedEvidenceFingerprint()))throw error(ApiError.REVISION_CONFLICT);if(!readiness.eligible())throw error(ApiError.ATTESTATION_NOT_ELIGIBLE);byte[] fingerprint=db.hash(e);
        var existing=db.jdbc.query("SELECT id FROM participation_attestations WHERE owner_id=? AND enrollment_id=? AND attestation_type='PARTICIPATION' AND locale=? AND evidence_fingerprint=?",(r,n)->r.getObject(1,UUID.class),actor,enrollment,command.locale(),fingerprint);if(!existing.isEmpty()){UUID id=existing.getFirst();db.remember(actor,"ATTESTATION_ISSUE",key,requestHash,"attestation_id",id);return new AttestationCreation(load(actor,id),false);}
        UUID id=UUID.randomUUID();Instant issued=db.jdbc.queryForObject("SELECT clock_timestamp()",Timestamp.class).toInstant();byte[] bytes=ParticipationHtml.render(id,command.locale(),issued,e);String snapshot=db.json(e);if(bytes.length>262144||snapshot.getBytes(StandardCharsets.UTF_8).length>1024*1024)throw error(ApiError.ATTESTATION_DOCUMENT_TOO_LARGE);
        db.jdbc.update("INSERT INTO participation_attestations(id,owner_id,enrollment_id,attestation_type,locale,evidence_fingerprint,snapshot_json,document_bytes,document_sha256,document_size,issued_at) VALUES(?,?,?,'PARTICIPATION',?,?,?::jsonb,?,?,?,?)",id,actor,enrollment,command.locale(),fingerprint,snapshot,bytes,digest(bytes),bytes.length,Timestamp.from(issued));db.remember(actor,"ATTESTATION_ISSUE",key,requestHash,"attestation_id",id);return new AttestationCreation(load(actor,id),true);
    }
    @Transactional(readOnly=true,isolation=Isolation.REPEATABLE_READ)
    public AttestationPage list(UUID actor,int page,int size){db.authorization.require(actor,"attestations.read");page(page,size);long total=db.jdbc.queryForObject("SELECT count(*) FROM participation_attestations WHERE owner_id=?",Long.class,actor);var items=db.jdbc.query("SELECT id FROM participation_attestations WHERE owner_id=? ORDER BY issued_at DESC,id LIMIT ? OFFSET ?",(r,n)->r.getObject(1,UUID.class),actor,size,(long)page*size).stream().map(id->load(actor,id).summary()).toList();return new AttestationPage(items,page,size,total);}
    @Transactional(readOnly=true)
    public AttestationView get(UUID actor,UUID id){db.authorization.require(actor,"attestations.read");return load(actor,id);}
    @Transactional(readOnly=true)
    public DocumentBytes document(UUID actor,UUID id){db.authorization.require(actor,"attestations.read");var rows=db.jdbc.query("SELECT document_bytes,document_sha256 FROM participation_attestations WHERE id=? AND owner_id=?",(r,n)->new DocumentBytes(r.getBytes(1),filename(id),hex(r.getBytes(2))),id,actor);if(rows.isEmpty())throw error(ApiError.RESOURCE_NOT_FOUND);return rows.getFirst();}
    private AttestationView load(UUID actor,UUID id){var rows=db.jdbc.query("SELECT enrollment_id,locale,evidence_fingerprint,snapshot_json,document_size,document_sha256,issued_at FROM participation_attestations WHERE id=? AND owner_id=?",(r,n)->{var e=db.mapper.readValue(r.getString("snapshot_json"),ParticipationEvidence.class);var d=new AttestationDocument("HTML","text/html; charset=UTF-8",filename(id),r.getLong("document_size"),hex(r.getBytes("document_sha256")));var s=new AttestationSummary(id,r.getObject("enrollment_id",UUID.class),"PARTICIPATION",r.getString("locale"),e.courseResourceId(),e.courseVersionId(),e.courseVersionNumber(),e.courseTitle(),e.participantName(),instant(r,"issued_at"),d);return new AttestationView(s,hex(r.getBytes("evidence_fingerprint")),e);},id,actor);if(rows.isEmpty())throw error(ApiError.RESOURCE_NOT_FOUND);return rows.getFirst();}
    private ParticipationEvidence evidence(UUID actor,UUID enrollment){
        var header=db.jdbc.query("SELECT e.*,u.display_name,u.revision AS profile_revision FROM learning_enrollments e JOIN user_accounts u ON u.id=e.owner_id WHERE e.id=? AND e.owner_id=?",(r,n)->new Header(r.getObject("course_resource_id",UUID.class),r.getObject("course_version_id",UUID.class),r.getInt("course_version_number"),r.getString("course_title"),r.getString("enrolled_locale"),r.getLong("profile_revision"),r.getString("display_name")),enrollment,actor);if(header.isEmpty())throw error(ApiError.RESOURCE_NOT_FOUND);var h=header.getFirst();
        var activities=db.jdbc.query("SELECT i.*,p.read_at,p.completed_at FROM learning_enrollment_activities i LEFT JOIN learning_activity_progress p ON p.enrollment_id=i.enrollment_id AND p.activity_version_id=i.activity_version_id WHERE i.enrollment_id=? ORDER BY i.position,i.activity_version_id",(r,n)->new ParticipationActivity(r.getObject("activity_id",UUID.class),r.getObject("activity_version_id",UUID.class),r.getInt("position"),r.getString("activity_title"),instant(r,"read_at"),instant(r,"completed_at")),enrollment);
        var quizzes=db.jdbc.query("SELECT DISTINCT ON(q.activity_version_id) q.* FROM learning_quiz_attempts q JOIN learning_enrollment_activities i ON i.enrollment_id=q.enrollment_id AND i.activity_id=q.activity_id AND i.activity_version_id=q.activity_version_id WHERE q.enrollment_id=? AND q.owner_id=? ORDER BY q.activity_version_id,q.attempt_number DESC,q.submitted_at DESC,q.id",(r,n)->new ParticipationQuiz(r.getObject("id",UUID.class),r.getObject("activity_id",UUID.class),r.getObject("activity_version_id",UUID.class),r.getObject("revision_id",UUID.class),r.getString("locale"),r.getInt("attempt_number"),r.getInt("score_points"),r.getInt("max_points"),r.getBoolean("passed"),r.getInt("pass_percent"),instant(r,"submitted_at")),enrollment,actor);
        var assessments=db.jdbc.query("SELECT DISTINCT ON(p.source_version_id) a.*,p.source_activity_id,p.source_version_id,p.source_locale FROM project_self_assessments a JOIN projects p ON p.id=a.project_id AND p.owner_id=a.owner_id AND p.current_revision_id=a.project_revision_id JOIN learning_enrollment_activities i ON i.enrollment_id=p.enrollment_id AND i.activity_id=p.source_activity_id AND i.activity_version_id=p.source_version_id WHERE p.enrollment_id=? AND p.owner_id=? ORDER BY p.source_version_id,a.evaluated_at DESC,a.assessment_number DESC,a.id",(r,n)->new ParticipationAssessment(r.getObject("id",UUID.class),r.getObject("project_id",UUID.class),r.getObject("project_revision_id",UUID.class),r.getObject("rubric_id",UUID.class),r.getObject("source_activity_id",UUID.class),r.getObject("source_version_id",UUID.class),r.getString("source_locale"),r.getInt("score_points"),r.getInt("max_points"),r.getInt("pass_points"),r.getBoolean("threshold_met"),r.getBoolean("needs_revision"),instant(r,"evaluated_at"),r.getBoolean("declared_by_user")),enrollment,actor);
        check(activities.size()<=10000&&quizzes.size()<=10000&&assessments.size()<=10000);var result=new ParticipationEvidence(enrollment,h.course(),h.version(),h.number(),h.title(),h.locale(),h.profileRevision(),h.name()==null||h.name().isBlank()?null:h.name(),false,false,activities,quizzes,assessments);if(db.json(result).getBytes(StandardCharsets.UTF_8).length>1024*1024)throw error(ApiError.ATTESTATION_DOCUMENT_TOO_LARGE);return result;
    }
    private static String filename(UUID id){return "attestation-"+id+".html";}
    private record Header(UUID course,UUID version,int number,String title,String locale,long profileRevision,String name) { }
}
